SELECT id FROM orders WHERE id NOT IN (2, NULL) ORDER BY id;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE sales(team, customer);
-- INSERT INTO sales VALUES('A',1),('A',1),('B',2),('B',3);
SELECT team FROM sales GROUP BY team HAVING COUNT(DISTINCT customer) >= 2 ORDER BY team;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE orders(status);
-- INSERT INTO orders VALUES('done'),('open'),('done');
SELECT SUM(CASE WHEN status='done' THEN 1 ELSE 0 END) FROM orders;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE customers(id);
-- INSERT INTO customers VALUES(1),(2);
-- CREATE TABLE orders(id,customer_id);
-- INSERT INTO orders VALUES(10,1),(11,1);
SELECT c.id FROM customers c LEFT JOIN orders o ON c.id=o.customer_id WHERE o.id IS NULL ORDER BY c.id;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE customers(id);
-- INSERT INTO customers VALUES(1),(2);
-- CREATE TABLE orders(id,customer_id);
-- INSERT INTO orders VALUES(10,1);
SELECT COUNT(*), COUNT(o.id) FROM customers c LEFT JOIN orders o ON c.id=o.customer_id WHERE c.id=2;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE orders(refund);
-- INSERT INTO orders VALUES(2),(NULL),(3);
SELECT SUM(COALESCE(refund, 0)) FROM orders;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE orders(refund INTEGER);
SELECT SUM(COALESCE(refund, 0)), COALESCE(SUM(refund), 0)
FROM orders;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE orders(refund INTEGER);
-- INSERT INTO orders VALUES(NULL),(NULL);
SELECT COUNT(*), COUNT(refund), SUM(COALESCE(refund, 0))
FROM orders;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE orders(refund INTEGER);
-- INSERT INTO orders VALUES(2),(NULL),(4);
SELECT AVG(refund), AVG(COALESCE(refund, 0))
FROM orders;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE orders(refund INTEGER);
-- INSERT INTO orders VALUES(2),(2),(NULL),(3);
SELECT SUM(refund), SUM(DISTINCT refund)
FROM orders;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE customers(id INTEGER);
-- INSERT INTO customers VALUES(1),(2),(3);
-- CREATE TABLE orders(id INTEGER, customer_id INTEGER, status TEXT);
-- INSERT INTO orders VALUES(10,1,'done'),(11,2,'open');
SELECT COUNT(*)
FROM customers AS c
LEFT JOIN orders AS o
    ON c.id = o.customer_id AND o.status = 'done'
WHERE o.id IS NULL;

-- 입력 데이터 전체 (SQLite)
-- CREATE TABLE customers(id); INSERT INTO customers VALUES(1),(2); CREATE TABLE orders(customer_id); INSERT INTO orders VALUES(1);
SELECT COUNT(*) FROM customers c JOIN orders o ON c.id=o.customer_id;
